#include <iostream>
#include <vector>
using namespace std;

long long powMod(long long base, long long exp, int mod) {
    long long res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

long long nCr(int n, int r, const vector<long long>& fact, int mod) {
    long long numerator = fact[n];
    long long denom = (fact[r] * fact[n - r]) % mod;
    return (numerator * powMod(denom, mod - 2, mod)) % mod;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int totalN;
    long long totalK;
    cin >> totalN >> totalK;

    const int MOD = 998244353;
    if (totalK > totalN - 1) {
        cout << 0 << "\n";
        return 0;
    }

    vector<long long> factorials(totalN + 1);
    factorials[0] = 1;
