        long long powerVal = powMod(remaining - i, totalN, MOD);
        long long term = (comb * powerVal) % MOD;
        if (i % 2 == 1) {
            term = -term;
        }
        totalCount = (totalCount + term + MOD) % MOD;
    }

    totalCount = (totalCount * nCr(totalN, remaining, factorials, MOD)) % MOD;
    if (totalK != 0) {
